package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec
var discFile *os.File
var discReader *bufio.Reader
var InputDone bool = false

func formatZZ_ZZ9_99(d decimal.Decimal, width int) string {
	// width includes '.' and ',' ; pattern like ZZ,ZZ9.99 -> width 9
	// Determine comma positions and dot position from picture width
	// For ZZ,ZZ9.99: width 9, dot at 6 (0-indexed? let's generic)
	// General: pictures used here all end with "9.99" => last 3 chars are "9.99" ? Actually "ZZ9.99" ends with 9.99
	// So we can derive: decimal part is 2 digits, dot before them.
