// helpers for numeric handling
func parsePrice(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	n := decimal.RequireFromString(s)
	return decimal.New(n.IntPart(), -2)
}

func parsePct(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	fmt.Sscanf(s, "%d", &v)
	return v
}

func truncDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func roundDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

func storePic9_5V99(d decimal.Decimal) decimal.Decimal {
	// keep scale 2, truncate, then keep low-order 7 digits (5+2)
	// truncation already to 2 decimals
	d = d.Truncate(2)
	// keep low-order digits: modulo 10^7
	mod := decimal.New(1, 7) // 10000000
	// work with integer representation (value *100)
	intVal := d.Shift(2) // may be negative? not here
	// emulate overflow: keep low-order digits preserving sign
	// intVal is integer-like (scale 0)
	sign := intVal.Sign()
	if sign < 0 {
		intVal = intVal.Abs()
	}
	intVal = intVal.Mod(mod)
	if sign < 0 {
		intVal = intVal.Neg()
	}
	return intVal.Shift(-2)
}

func storePic9_8V99(d decimal.Decimal) decimal.Decimal {
	d = d.Truncate(2)
	mod := decimal.New(1, 10) // 10 digits = 8+2
	intVal := d.Shift(2)
	sign := intVal.Sign()
	if sign < 0 {
		intVal = intVal.Abs()
	}
	intVal = intVal.Mod(mod)
	if sign < 0 {
		intVal = intVal.Neg()
	}
	return intVal.Shift(-2)
}

// format for ZZ,ZZ9.99 (width 9) and ZZ,ZZZ,ZZ9.99 (width 13)
func formatEdited(d decimal.Decimal, pic string) string {
	width := len(pic)
	// find dot position
	dotIdx := strings.Index(pic, ".")
	var intPic string
	var decDigits int
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decDigits = width - dotIdx - 1
	} else {
		intPic = pic
		decDigits = 0
	}
	// integer part picture length
	intWidth := len(intPic)
	// Ensure d is truncated to decDigits (COBOL MOVE would truncate)
	d = d.Truncate(int32(decDigits))
	// Get integer part and decimal part
	// Use absolute value? No negative handling needed but implement
	sign := ""
	if d.Sign() < 0 {
		sign = "-"
		d = d.Abs()
	}
	// integer digits: drop high-order if overflow
	intPart := d.IntPart() // truncates toward zero
	intStr := fmt.Sprintf("%d", intPart)
	// overflow: keep low-order digits that fit in number of digit positions
	// count digit positions in intPic: number of '9' and 'Z'
	digitSlots := 0
	for _, c := range intPic {
		if c == '9' || c == 'Z' {
			digitSlots++
		}
	}
	if len(intStr) > digitSlots {
		intStr = intStr[len(intStr)-digitSlots:]
	}
	// pad with leading zeros to digitSlots
	if len(intStr) < digitSlots {
		intStr = strings.Repeat("0", digitSlots-len(intStr)) + intStr
	}
	// Now build formatted integer part with commas and Z suppression
	// intPic contains commas at fixed positions
	// Walk intPic left to right, mapping digitSlots
	resultInt := make([]byte, intWidth)
	// intStr index
	// intPic may contain ','
	digitIdx := 0
	for i := 0; i < intWidth; i++ {
		c := intPic[i]
		if c == ',' {
			resultInt[i] = ','
		} else {
			// Z or 9
			resultInt[i] = intStr[digitIdx]
			digitIdx++
		}
	}
	// Z suppression: leading zeros replaced with spaces, commas in suppressed zone become spaces
	// Find last Z position? Actually all Z's that are leading and zero should be spaces.
	// COBOL: each 'Z' that is still leading zero becomes space; if a comma is between suppressed digits, it also becomes space.
	// Determine if we have any non-zero digit before position.
	// We need to know which positions correspond to digits.
	// Simple algorithm: scan resultInt left to right; keep flag suppressed=true until we encounter a non-zero digit or a '9' position with zero that is mandatory.
	// For '9' positions, we stop suppression and print digit (even if zero).
	// For 'Z' positions, if suppressed and digit is '0' => space, else digit and suppression ends.
	suppressed := true
	for i := 0; i < intWidth; i++ {
		c := intPic[i]
		if c == ',' {
			continue
		}
		if c == '9' {
			suppressed = false
			// digit stays as is (could be zero)
		} else if c == 'Z' {
			if suppressed {
				if resultInt[i] == '0' {
					resultInt[i] = ' '
				} else {
					suppressed = false
				}
			}
		}
	}
	// commas that are in suppressed zone become spaces: a comma is suppressed if every digit to its left is suppressed (i.e., all digit positions left of comma are spaces)
	for i := 0; i < intWidth; i++ {
		if intPic[i] == ',' {
			// check if any non-space digit to left
			hasNonSpace := false
			for j := 0; j < i; j++ {
				if intPic[j] != ',' && resultInt[j] != ' ' {
					hasNonSpace = true
					break
				}
			}
			// also check if any non-suppressed zero digit to left? Already covered because it would be non-space ('0' for mandatory 9 would be '0' not space)
			// Additionally, if all digits to right are suppressed? No, comma stays only if there is non-space to left
			if !hasNonSpace {
				resultInt[i] = ' '
			}
			// also if no non-space to right? Actually COBOL still spaces leading commas, trailing commas not relevant
		}
	}

	// Build decimal part
	decStr := ""
	if decDigits > 0 {
		// get fractional digits
		// d.Shift(decDigits) fractional part
		shifted := d.Shift(int32(decDigits))
		// fractional part: shifted mod 10^decDigits
		// Use IntPart after shifting but need to handle truncated value
		// Extract decimal digits from string representation with proper truncation
		// Use d.Truncate approach to get exact decimal digits
		// Use string formatting with truncation
		// Compute int representation
		intRep := shifted.IntPart() // integer of d*10^decDigits truncated
		// intRep % 10^decDigits is decimal part
		pow := int64(1)
		for i := 0; i < decDigits; i++ {
			pow *= 10
		}
		rem := intRep % pow
		if rem < 0 {
			rem = -rem
		}
		decStr = fmt.Sprintf("%0*d", decDigits, rem)
		return sign + string(resultInt) + "." + decStr
	}
	return sign + string(resultInt)
}

func formatWSPriceEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZ9.99")
}
func formatWSTotalEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZZ,ZZ9.99")
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func READPARA() {
	line, err := discReader.ReadString('\n')
	if err != nil {
		// EOF: if line has content without newline, process it? COBOL LINE SEQUENTIAL: last line may not have newline
		if len(line) > 0 {
			// handle line without newline as successful read
			// trim trailing \r\n already not present
			line = strings.TrimRight(line, "\r\n")
			if len(line) < 15 {
				line = line + strings.Repeat(" ", 15-len(line))
			}
			if len(line) > 15 {
				line = line[:15]
			}
			discRec.DrItem = line[0:6]
			discRec.DrPrice = parsePrice(line[6:13])
			discRec.DrPct = parsePct(line[13:15])
			return
		}
		WsEofFlag = "Y"
		InputDone = true
		return
	}
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	discRec.DrItem = line[0:6]
	discRec.DrPrice = parsePrice(line[6:13])
	discRec.DrPct = parsePct(line[13:15])
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	tmp := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	tmp = roundDecimal(tmp, 2)
	WsDiscount = storePic9_5V99(tmp)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	tmp2 := discRec.DrPrice.Sub(WsDiscount)
	tmp2 = truncDecimal(tmp2, 2)
	WsNet = storePic9_5V99(tmp2)
	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = WsTotalNet.Add(WsNet)
	WsTotalNet = storePic9_8V99(WsTotalNet)
	WsCount++
	WsPriceEd = formatWSPriceEd(discRec.DrPrice)
	WsDiscEd = formatWSPriceEd(WsDiscount)
	WsNetEd = formatWSPriceEd(WsNet)
	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-PCT is PIC 9(2) numeric DISPLAY -> zero-padded width 2
	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatWSTotalEd(WsTotalNet)
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer discFile.Close()
	discReader = bufio.NewReader(discFile)

	// OPEN INPUT DISC-FILE
	// PERFORM READ-PARA
	READPARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !InputDone {
		PROCESSPARA()
	}
	// CLOSE DISC-FILE
	// PERFORM SUMMARY-PARA
	SUMMARYPARA()
}
